'use client';

import clsx from 'clsx';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

export default function ActiveLink({
  isActive,
  searchParams,
  children,
}: {
  isActive: boolean;
  searchParams: string;
  children: React.ReactNode;
}) {
  const pathname = usePathname();

  return (
    <Link
      className={clsx('rounded-lg px-3 py-1 text-sm font-medium no-underline', {
        'bg-gray-700 text-gray-100 hover:bg-gray-500 hover:text-white':
          !isActive,
        'bg-blue-600 text-white': isActive,
      })}
      href={pathname + '?' + searchParams}
    >
      {children}
    </Link>
  );
}

import { Boundary } from '#/ui/boundary';
import { ExternalLink } from '#/ui/external-link';
import { Suspense } from 'react';
import ActiveLink from './active-link';
import Client from './client';

const options = [
  { name: 'Sort', value: 'sort', items: ['asc', 'desc'] },
  { name: 'Page', value: 'page', items: ['1', '2', '3'] },
  { name: 'Items Per Page', value: 'perPage', items: ['10', '25', '100'] },
];

export default async function Page(props: { searchParams: Promise<any> }) {
  const searchParams = await props.searchParams;
  return (
    <div className="prose prose-sm prose-invert max-w-none">
      <h1 className="text-lg font-bold">
        Updating <code>searchParams</code>
      </h1>
      <p>
        The <code>useSearchParams</code> hook returns a read only version of{' '}
        <code>URLSearchParams</code>. You can use{' '}
        <code>useRouter&#40;&#41;</code> or <code>&lt;Link&gt;</code> to set new{' '}
        <code>searchParams</code>. After a navigation is performed, the current{' '}
        <code>page.js</code> will receive an updated <code>searchParams</code>{' '}
        prop.
      </p>
      <div className="mt-12 space-y-12">
        <div className="space-y-4">
          <Boundary color="blue" label={['From the Client']}>
            <h3 className="mt-0">
              Using <code>useRouter&#40;&#41;</code>
            </h3>

            <Suspense>
              <Client options={options} />
            </Suspense>
          </Boundary>

          <ExternalLink href="https://nextjs.org/docs/app/api-reference/functions/use-search-params">
            Docs
          </ExternalLink>
        </div>

        <div className="space-y-4">
          <Boundary label={['From the Server']}>
            <h3 className="mt-0">
              Using <code>&lt;Link&gt;</code>
            </h3>

            <div className="flex items-center gap-6">
              {options.map((option) => {
                return (
                  <div key={option.name}>
                    <div className="text-gray-400">{option.name}</div>

                    <div className="mt-1 flex gap-2">
                      {option.items.map((item, i) => {
                        const isActive =
                          // set the first item as active if no search param is set
                          (!searchParams[option.value] && i === 0) ||
                          // otherwise check if the current item is the active one
                          item === searchParams[option.value];

                        // create new searchParams object for easier manipulation
                        const params = new URLSearchParams(searchParams);
                        params.set(option.value, item);
                        return (
                          <ActiveLink
                            key={item}
                            isActive={isActive}
                            searchParams={params.toString()}
                          >
                            {item}
                          </ActiveLink>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </Boundary>

          <ExternalLink href="https://nextjs.org/docs/app/api-reference/file-conventions/page">
            Docs
          </ExternalLink>
        </div>
      </div>
    </div>
  );
}

'use client';

import clsx from 'clsx';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { useCallback, useMemo } from 'react';

export default function Client({
  options,
}: {
  options: { name: string; value: string; items: string[] }[];
}) {
  const searchParams = useSearchParams()!;
  const pathname = usePathname();
  const router = useRouter();

  const selectedOptions = useMemo<URLSearchParams>(() => {
    // Get the initial selected options from the URL's searchParams
    const params = new URLSearchParams(searchParams);

    // Preselect the first value of each option if its not
    // included in the current searchParams
    options.forEach((option) => {
      if (!searchParams.has(option.value)) {
        params.set(option.value, option.items[0]);
      }
    });

    return params;
  }, [searchParams, options]);

  const updateSearchParam = useCallback(
    (name: string, value: string) => {
      // Merge the current searchParams with the new param set
      const params = new URLSearchParams(searchParams);
      params.set(name, value);

      // Perform a new navigation to the updated URL. The current `page.js` will
      // receive a new `searchParams` prop with the updated values.
      router.push(pathname + '?' + params.toString()); // or router.replace()
    },
    [router, pathname, searchParams],
  );

  return (
    <>
      <div className="flex items-center gap-6">
        {options.map((option) => (
          <div key={option.name}>
            <div className="text-gray-400">{option.name}</div>

            <div className="mt-1 flex gap-2">
              {option.items.map((item) => {
                const isActive = selectedOptions.get(option.value) === item;

                return (
                  <button
                    key={item}
                    onClick={() => updateSearchParam(option.value, item)}
                    className={clsx(
                      'rounded-lg px-3 py-1 text-sm font-medium',
                      {
                        'bg-gray-700 text-gray-100 hover:bg-gray-500 hover:text-white':
                          !isActive,
                        'bg-blue-600 text-white': isActive,
                      },
                    )}
                  >
                    {item}
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </>
  );
}

